"""Camera/proprioception-only controller for the single recorded episode.
No simulator state or benchmark solution is used. Each submitted target is journaled.
Run commands: observe NAME; move X Y Z RX RY RZ FINGER SECONDS;
              joint Q1 ... Q7 FINGER SECONDS; grip FINGER SECONDS.
Euler XYZ angles are degrees in the world frame. TCP is the reported fingertip site.
"""
import json, sys, pathlib, time
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot
OUT=pathlib.Path('/app/output'); OUT.mkdir(exist_ok=True)
POSITIONS=np.array([[0,0,.333],[0,0,0],[0,-.316,0],[.0825,0,0],[-.0825,.384,0],[0,0,0],[.088,0,0]])
ANGLES=[0,-90,90,90,-90,90,90]
LIMITS=np.array([[-2.8973,2.8973],[-1.7628,1.7628],[-2.8973,2.8973],[-3.0718,-.0698],[-2.8973,2.8973],[-.0175,3.7525],[-2.8973,2.8973]])
def fk(q):
 T=np.eye(4);T[:3,:3]=Rotation.from_euler('z',1.57).as_matrix();T[:3,3]=[0,-.4,.78]
 for p,a,j in zip(POSITIONS,ANGLES,q):
  A=np.eye(4);A[:3,3]=p;A[:3,:3]=Rotation.from_euler('x',a,degrees=True).as_matrix()@Rotation.from_euler('z',j).as_matrix();T=T@A
 A=np.eye(4);A[:3,3]=[0,0,.2];A[:3,:3]=Rotation.from_euler('z',-np.pi/4).as_matrix()
 return T@A

def ik(p, rot, q, regular=.0005):
 def error(x):
  T=fk(x);dr=Rotation.from_matrix(rot@T[:3,:3].T).as_rotvec()
  return np.r_[T[:3,3]-p,dr*.25,(x-q)*regular]
 sol=least_squares(error,np.clip(q,LIMITS[:,0]+1e-5,LIMITS[:,1]-1e-5),bounds=(LIMITS[:,0]+1e-6,LIMITS[:,1]-1e-6),max_nfev=200)
 T=fk(sol.x); pe=np.linalg.norm(T[:3,3]-p);re=np.linalg.norm(Rotation.from_matrix(rot@T[:3,:3].T).as_rotvec())
 if pe>.008 or re>.06:raise RuntimeError(f'IK unreachable position {pe:.4f} orientation {re:.4f}')
 return sol.x

class Controller:
 def __init__(self):
  self.r=Robot();self.obs=self.r.get_obs(cameras=['forward','left','right'],video='none');self.now=np.array(self.obs.meta['proprio']['now']);self.seq=len(list(OUT.glob('act_*')))
 def save(self,res,label):
  self.obs=res;self.now=np.array(res.meta['proprio']['now']);self.seq+=1
  path=OUT/f'act_{self.seq:04d}_{label}';res.save(path)
  print(json.dumps({'path':str(path),'steps':res.meta['control_steps'],'done':res.done,'reason':res.meta['reason'],'q':self.now[:7].tolist(),'fingers':self.now[14:16].tolist(),'tcp':self.now[16:23].tolist()}),flush=True)
 def execute(self,A,label):
  A=np.asarray(A);stamp=time.time_ns();np.save(OUT/f'targets_{stamp}_{label}.npy',A)
  with open(OUT/'journal.jsonl','a') as f:f.write(json.dumps({'targets':f'targets_{stamp}_{label}.npy','dt':.1,'interpolate':'linear','label':label})+'\n')
  for k in range(0,len(A),100):
   res=self.r.submit('joint_position',A[k:k+100],dt=.1,cameras=['forward','left','right','wrist'],video='none',note=label)
   self.save(res,label)
   if res.done:return
 def joint(self,q,f,seconds,label='joint'):
  n=max(1,int(round(seconds/.1)));A=np.linspace(np.r_[self.now[:7],self.now[14:16]],np.r_[q,f,f],n+1)[1:];self.execute(A,label)
 def move(self,p,rot,f,seconds,label='move'):
  # Cartesian interpolation keeps held tools away from the table during transport.
  n=max(1,int(round(seconds/.1)));p0=self.now[16:19];R0=Rotation.from_quat(self.now[[20,21,22,19]]).as_matrix();dr=Rotation.from_matrix(rot@R0.T).as_rotvec();q=self.now[:7].copy();A=[]
  for t in np.linspace(0,1,n+1)[1:]:
   smooth=t*t*(3-2*t);pt=p0+(p-p0)*smooth;Rt=Rotation.from_rotvec(dr*smooth).as_matrix()@R0
   q=ik(pt,Rt,q);A.append(np.r_[q,f,f])
  self.execute(A,label)
 def observe(self,label):self.save(self.r.get_obs(include_depth=True,video='none'),label)

def main():
 c=Controller();args=sys.argv[1:];cmd=args.pop(0)
 if cmd=='observe':c.observe(args[0] if args else 'observe')
 elif cmd=='move':
  a=list(map(float,args));c.move(np.array(a[:3]),Rotation.from_euler('xyz',a[3:6],degrees=True).as_matrix(),a[6],a[7])
 elif cmd=='joint':
  a=list(map(float,args));c.joint(np.array(a[:7]),a[7],a[8])
 elif cmd=='grip':
  a=list(map(float,args));c.joint(c.now[:7],a[0],a[1],'grip')
 elif cmd=='check':print('FK',fk(c.now[:7]),'reported',c.now[16:23])
 else:raise ValueError(cmd)
if __name__=='__main__':main()
